import json
import random
import os

items = []

def add(q, a, w, cat, exp):
    opts = [a] + list(w)
    random.shuffle(opts)
    items.append({
        "id": f"t500-{len(items)+1}",
        "gameId": "trivia_spark",
        "category": cat,
        "question": q,
        "options": opts,
        "correctAnswer": a,
        "explanation": exp
    })

# We import the 70 history questions from make_500.py
exec(open('scripts/make_500.py', 'r', encoding='utf-8').read())
print(f"Base items count: {len(items)}")

